CREATE TABLE compensation_revision_overrides (
                id TEXT PRIMARY KEY,
                revision_id TEXT NOT NULL REFERENCES compensation_revisions(id) ON DELETE CASCADE,
                parameter TEXT NOT NULL,
                value INTEGER NOT NULL,
                personnel_id TEXT REFERENCES personnel(id) ON DELETE RESTRICT,
                UNIQUE(revision_id, parameter, personnel_id)
            );
CREATE TABLE compensation_revisions (
                id TEXT PRIMARY KEY,
                reason TEXT NOT NULL,
                title TEXT NOT NULL,
                effective_from TEXT NOT NULL,
                effective_to TEXT,
                decision_date TEXT,
                signed_at TEXT,
                description TEXT,
                status TEXT NOT NULL DEFAULT 'DRAFT',
                scope TEXT NOT NULL DEFAULT 'ALL_PERSONNEL',
                personnel_ids_json TEXT NOT NULL DEFAULT '[]',
                personnel_group TEXT,
                created_at TEXT,
                updated_at TEXT
            );
CREATE TABLE institution_settings (
                period_id TEXT PRIMARY KEY REFERENCES payroll_periods(id) ON DELETE CASCADE,
                settings_json TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
