CREATE TABLE personnel (
                id TEXT PRIMARY KEY,
                tc_no TEXT UNIQUE NOT NULL,
                ad TEXT NOT NULL,
                soyad TEXT NOT NULL,
                grup TEXT NOT NULL,
                unvan TEXT,
                sgk_sicil_no TEXT NOT NULL DEFAULT '',
