CREATE TABLE personnel_tax_opening (
                id TEXT PRIMARY KEY,
                personnel_id TEXT NOT NULL REFERENCES personnel(id) ON DELETE CASCADE,
                year INTEGER NOT NULL,
                gv_cumulative_opening INTEGER,
                effective_from_period_id TEXT REFERENCES payroll_periods(id) ON DELETE CASCADE,
                asgari_gv_cumulative_opening INTEGER,
                asgari_gv_effective_from_period_id TEXT REFERENCES payroll_periods(id) ON DELETE CASCADE,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                CONSTRAINT unique_personnel_tax_opening_year UNIQUE(personnel_id, year)
            );
CREATE TABLE retro_adjustment_allocations (
                id TEXT PRIMARY KEY,
                batch_id TEXT NOT NULL REFERENCES retro_adjustment_batches(id) ON DELETE CASCADE,
                personnel_id TEXT NOT NULL REFERENCES personnel(id) ON DELETE RESTRICT,
                source_period_id TEXT NOT NULL REFERENCES payroll_periods(id) ON DELETE RESTRICT,
                earning_code TEXT NOT NULL,
                original_recognized_amount INTEGER NOT NULL,
                previous_retro_amount INTEGER NOT NULL DEFAULT 0,
                target_amount INTEGER NOT NULL,
                delta_amount INTEGER NOT NULL,
                sgk_treatment TEXT NOT NULL,
                income_tax_treatment TEXT NOT NULL,
                stamp_tax_treatment TEXT NOT NULL,
                original_pek INTEGER NOT NULL DEFAULT 0,
                retro_pek_delta INTEGER NOT NULL DEFAULT 0,
                adjusted_pek INTEGER NOT NULL DEFAULT 0,
                worker_sgk_delta INTEGER NOT NULL DEFAULT 0,
                worker_unemployment_delta INTEGER NOT NULL DEFAULT 0,
                employer_sgk_delta INTEGER NOT NULL DEFAULT 0,
                employer_unemployment_delta INTEGER NOT NULL DEFAULT 0,
                original_employer_lower_bound INTEGER NOT NULL DEFAULT 0,
                target_employer_lower_bound INTEGER NOT NULL DEFAULT 0,
                employer_lower_bound_delta INTEGER NOT NULL DEFAULT 0,
                employer_lower_bound_premium_delta INTEGER NOT NULL DEFAULT 0,
                original_source_carry_json TEXT,
                target_source_carry_json TEXT,
                payable_settlement_amount INTEGER NOT NULL DEFAULT 0,
                offset_settlement_amount INTEGER NOT NULL DEFAULT 0,
                recoverable_amount INTEGER NOT NULL DEFAULT 0,
                metadata TEXT
            );
CREATE TABLE retro_adjustment_batches (
                id TEXT PRIMARY KEY,
                revision_id TEXT NOT NULL REFERENCES compensation_revisions(id) ON DELETE RESTRICT,
                personnel_id TEXT NOT NULL REFERENCES personnel(id) ON DELETE RESTRICT,
                payment_date TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'CALCULATED',
                settlement_status TEXT NOT NULL DEFAULT 'UNSETTLED',
                total_gross_delta INTEGER NOT NULL,
                payable_settlement_amount INTEGER NOT NULL DEFAULT 0,
                offset_settlement_amount INTEGER NOT NULL DEFAULT 0,
                recovered_amount INTEGER NOT NULL DEFAULT 0,
                recoverable_amount INTEGER NOT NULL DEFAULT 0,
                outstanding_receivable INTEGER NOT NULL DEFAULT 0,
                description TEXT,
                created_at TEXT,
                calculated_at TEXT,
                finalized_at TEXT
            );
CREATE TABLE sick_leave_records (
                id TEXT PRIMARY KEY,
                personnel_id TEXT NOT NULL REFERENCES personnel(id) ON DELETE CASCADE,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
CREATE INDEX idx_payroll_records_personnel ON payroll_records(personnel_id);
CREATE INDEX idx_payroll_records_period ON payroll_records(period_id);
CREATE INDEX idx_attendance_records_period ON attendance_records(period_id);
CREATE INDEX idx_tax_opening_personnel_year ON personnel_tax_opening(personnel_id, year);
CREATE INDEX idx_sick_leave_personnel ON sick_leave_records(personnel_id);
CREATE INDEX idx_sick_leave_start_date ON sick_leave_records(start_date);
CREATE UNIQUE INDEX idx_payroll_periods_tax_year_month
         ON payroll_periods(tax_year, tax_month);
CREATE UNIQUE INDEX idx_payroll_records_accrual_id
                 ON payroll_records(accrual_id);
CREATE UNIQUE INDEX idx_payroll_records_one_normal
                 ON payroll_records(personnel_id, period_id)
                 WHERE accrual_type = 'NORMAL';
CREATE UNIQUE INDEX idx_payroll_records_payment_sequence
                 ON payroll_records(personnel_id, payment_date, sequence);
CREATE INDEX idx_payroll_records_accrual_order
                 ON payroll_records(personnel_id, payment_date, sequence, accrual_id);
CREATE INDEX idx_compensation_revision_overrides_revision
                ON compensation_revision_overrides(revision_id);
CREATE UNIQUE INDEX idx_compensation_revision_overrides_unique_scope
                ON compensation_revision_overrides(revision_id, parameter, COALESCE(personnel_id, ''));
CREATE INDEX idx_retro_batches_personnel_payment
                ON retro_adjustment_batches(personnel_id, payment_date, id);
CREATE INDEX idx_retro_allocations_source
                ON retro_adjustment_allocations(personnel_id, source_period_id, earning_code);
CREATE UNIQUE INDEX idx_retro_allocations_batch_source_code
                ON retro_adjustment_allocations(batch_id, source_period_id, earning_code);
CREATE INDEX idx_retro_batches_revision_personnel
                ON retro_adjustment_batches(revision_id, personnel_id, payment_date, id);
COMMIT;